    "questionNumber": 376,
    "question": "Read the following five statements (A-E) regarding Mendelian genetics and chromosomal theory:\n(A) Sutton and Boveri argued that the pairing and separation of a pair of chromosomes would lead to the segregation of a pair of factors they carried.\n(B) Thomas Hunt Morgan demonstrated that tightly linked genes showed very high frequencies of recombination.\n(C) In human females, Turner syndrome is characterized by the presence of 45 chromosomes with an X0 karyotype.\n(D) Sickle-cell anaemia is an autosome-linked dominant trait.\n(E) Phenylketonuria is caused by the absence of the enzyme phenylalanine hydroxylase.\nWhich of the above statements are CORRECT?",
