    "id": "principles-of-inheritance-mcq-437",
    "questionNumber": 437,
    "question": "A three-point test cross in Drosophila involving three linked genes—cinnamon (cn), black (b), and vestigial (vg)—yields the following recombination frequencies:\nDistance between b and cn = 9 cM;\nDistance between cn and vg = 9.5 cM;\nDistance between b and vg = 18.5 cM.\nWhat is the correct linear order of these three genes on the chromosome?",
    "options": {
      "A": "b - cn - vg (or vg - cn - b)",
      "B": "The genes are on three different non-homologous chromosomes",
      "C": "cn - b - vg",
      "D": "b - vg - cn"
    },
    "optionsList": [
      "b - cn - vg (or vg - cn - b)",
      "The genes are on three different non-homologous chromosomes",
      "cn - b - vg",
      "b - vg - cn"
    ],
    "correctAnswer": "A",
    "correctOption": "A",
    "correctIndex": 0,
    "explanation": "1. CONCEPT:\nThree-point genetic mapping.\n\n2. STEP-BY-STEP SOLUTION:\nThe largest distance is between b and vg (18.5 cM), which represents the two flanking outside markers. The sum of the two shorter distances (b-cn = 9 cM + cn-vg = 9.5 cM = 18.5 cM) exactly equals the total span. Therefore, cn lies in the middle: b - cn - vg.\n\n3. FINAL ANSWER:\nOption A: b - cn - vg (or vg - cn - b)\n\n4. WHY OTHER OPTIONS ARE WRONG:\nAny other gene order fails to satisfy additive map distances.",
    "solutionStructured": {
      "concept": "Three-point genetic mapping.",
      "stepByStep": "The largest distance is between b and vg (18.5 cM), which represents the two flanking outside markers. The sum of the two shorter distances (b-cn = 9 cM + cn-vg = 9.5 cM = 18.5 cM) exactly equals the total span. Therefore, cn lies in the middle: b - cn - vg.",
      "finalAnswer": "Option A: b - cn - vg (or vg - cn - b)",
      "whyOtherOptionsWrong": "Any other gene order fails to satisfy additive map distances."
    },
