    "question": "In a family pedigree spanning three generations, a metabolic disease affects both males and females with equal frequency. Unaffected carrier parents routinely produce affected children (~25% risk), and consanguineous marriage significantly elevates disease incidence. What is the most probable pattern of inheritance and which disorder matches this profile?",
