    "id": "principles-of-inheritance-mcq-474",
    "questionNumber": 474,
    "question": "A 25-year-old male with tall stature, poor muscular coordination, mild intellectual impairment, bilateral gynaecomastia, and azoospermia undergoes cytogenetic karyotyping. Peripheral blood lymphocytes reveal 47 chromosomes with a single Barr body. What is the definitive chromosomal diagnosis and the origin of the extra chromosome?",
    "options": {
      "A": "Turner syndrome (45, X0); resulting from mitotic loss of an autosome",
      "B": "Superfemale syndrome (47, XXX); resulting from polyploidy",
      "C": "Klinefelter syndrome (47, XXY); resulting from maternal or paternal meiotic non-disjunction of sex chromosomes",
      "D": "Down syndrome (47, +21); resulting from paternal Robertsonian translocation"
    },
    "optionsList": [
      "Turner syndrome (45, X0); resulting from mitotic loss of an autosome",
      "Superfemale syndrome (47, XXX); resulting from polyploidy",
      "Klinefelter syndrome (47, XXY); resulting from maternal or paternal meiotic non-disjunction of sex chromosomes",
      "Down syndrome (47, +21); resulting from paternal Robertsonian translocation"
    ],
    "correctAnswer": "C",
    "correctOption": "C",
    "correctIndex": 2,
    "explanation": "1. CONCEPT:\nClinical and cytogenetic analysis of Klinefelter syndrome.\n\n2. STEP-BY-STEP SOLUTION:\n47 chromosomes with XXY produces a phenotypic male with gynaecomastia and azoospermia. The presence of one Barr body confirms the inactivation of one extra X chromosome (Number of Barr bodies = X chromosomes - 1 = 2 - 1 = 1). This arises from non-disjunction during gametogenesis.\n\n3. FINAL ANSWER:\nOption C: Klinefelter syndrome (47, XXY); resulting from maternal or paternal meiotic non-disjunction of sex chromosomes\n\n4. WHY OTHER OPTIONS ARE WRONG:\nTurner syndrome has zero Barr bodies and affects females; Down syndrome involves autosome 21.",
    "solutionStructured": {
      "concept": "Clinical and cytogenetic analysis of Klinefelter syndrome.",
      "stepByStep": "47 chromosomes with XXY produces a phenotypic male with gynaecomastia and azoospermia. The presence of one Barr body confirms the inactivation of one extra X chromosome (Number of Barr bodies = X chromosomes - 1 = 2 - 1 = 1). This arises from non-disjunction during gametogenesis.",
      "finalAnswer": "Option C: Klinefelter syndrome (47, XXY); resulting from maternal or paternal meiotic non-disjunction of sex chromosomes",
      "whyOtherOptionsWrong": "Turner syndrome has zero Barr bodies and affects females; Down syndrome involves autosome 21."
    },
